import {
  ConflictException,
  Injectable,
  UnauthorizedException,
} from '@nestjs/common';
import { JwtService } from '@nestjs/jwt';
import * as bcrypt from 'bcrypt';
import { randomBytes } from 'crypto';
import { PrismaService } from '../prisma/prisma.service';
import { LoginDto } from './dto/login.dto';
import { RegisterDto } from './dto/register.dto';
import type { JwtPayload } from './auth.types';
import { LOGIN_FAILED_MESSAGE } from './auth.constants';

const SALT_ROUNDS = 12;

@Injectable()
export class AuthService {
  constructor(
    private readonly prisma: PrismaService,
    private readonly jwt: JwtService,
  ) {}

  async register(dto: RegisterDto) {
    const email = dto.email;
    const existing = await this.prisma.user.findUnique({
      where: { email },
    });
    if (existing) {
      throw new ConflictException('Email already in use');
    }

    const passwordHash = await bcrypt.hash(dto.password, SALT_ROUNDS);

    const user = await this.prisma.user.create({
      data: {
        email,
        passwordHash,
        ...(dto.displayName != null ? { displayName: dto.displayName } : {}),
      },
      select: { id: true, email: true, displayName: true },
    });

    return user;
  }

  async login(dto: LoginDto) {
    const user = await this.prisma.user.findUnique({
      where: { email: dto.email },
      select: { id: true, email: true, passwordHash: true },

    });
    if (!user) throw new UnauthorizedException(LOGIN_FAILED_MESSAGE);

    const ok = await bcrypt.compare(dto.password, user.passwordHash);
    if (!ok) throw new UnauthorizedException(LOGIN_FAILED_MESSAGE);

    const payload: JwtPayload = { sub: user.id, email: user.email };
    const access_token = await this.jwt.signAsync(payload);
    return { access_token };
  }

  async generateJwt(userId: string, email: string): Promise<string> {
    const payload: JwtPayload = { sub: userId, email };
    return this.jwt.signAsync(payload);
  }

  /**
   * Link or create user by email for OAuth providers (same email = same account).
   * Uses a random password hash so password login cannot succeed for OAuth-only users.
   */
  async findOrCreateOAuthUser(email: string) {
    const existing = await this.prisma.user.findUnique({
      where: { email },
      select: { id: true, email: true },
    });
    if (existing) return existing;

    const passwordHash = await bcrypt.hash(
      `oauth:${randomBytes(32).toString('hex')}`,
      SALT_ROUNDS,
    );
    return this.prisma.user.create({
      data: { email, passwordHash },
      select: { id: true, email: true },
    });
  }
}

import { UnauthorizedException } from '@nestjs/common';
import { JwtService } from '@nestjs/jwt';
import { Test } from '@nestjs/testing';
import * as bcrypt from 'bcrypt';
import { PrismaService } from '../prisma/prisma.service';
import { LOGIN_FAILED_MESSAGE } from './auth.constants';
import { AuthService } from './auth.service';

describe('AuthService', () => {
  describe('login', () => {
    let service: AuthService;
    const prisma = {
      user: {
        findUnique: jest.fn(),
        create: jest.fn(),
      },
    };

    beforeEach(async () => {
      jest.clearAllMocks();
      const moduleRef = await Test.createTestingModule({
        providers: [
          AuthService,
          { provide: PrismaService, useValue: prisma },
          {
            provide: JwtService,
            useValue: { signAsync: jest.fn().mockResolvedValue('jwt-token') },
          },
        ],
      }).compile();

      service = moduleRef.get(AuthService);
    });

    function expectLoginFailed(err: unknown) {
      expect(err).toBeInstanceOf(UnauthorizedException);
      expect((err as UnauthorizedException).getResponse()).toMatchObject({
        message: LOGIN_FAILED_MESSAGE,
        statusCode: 401,
      });
    }

    it('uses the same error when user does not exist', async () => {
      prisma.user.findUnique.mockResolvedValue(null);
      try {
        await service.login({ email: 'missing@example.com', password: 'Password123!' });
      } catch (e) {
        expectLoginFailed(e);
      }
    });

    it('uses the same error when password is wrong', async () => {
      const hash = await bcrypt.hash('CorrectPass123!', 12);
      prisma.user.findUnique.mockResolvedValue({
        id: 'u1',
        email: 'user@example.com',
        passwordHash: hash,
      });

      try {
        await service.login({ email: 'user@example.com', password: 'WrongPass123!' });
      } catch (e) {
        expectLoginFailed(e);
      }
    });

    it('returns the exact same message string for unknown user and wrong password', async () => {
      prisma.user.findUnique.mockResolvedValue(null);
      let missingUserMsg = '';
      try {
        await service.login({ email: 'ghost@example.com', password: 'Password123!' });
      } catch (e) {
        missingUserMsg = String(
          ((e as UnauthorizedException).getResponse() as { message: string }).message,
        );
      }

      const hash = await bcrypt.hash('RightPass123!', 12);
      prisma.user.findUnique.mockResolvedValue({
        id: 'u2',
        email: 'real@example.com',
        passwordHash: hash,
      });
      let badPasswordMsg = '';
      try {
        await service.login({ email: 'real@example.com', password: 'WrongPass123!' });
      } catch (e) {
        badPasswordMsg = String(
          ((e as UnauthorizedException).getResponse() as { message: string }).message,
        );
      }

      expect(missingUserMsg).toBe(badPasswordMsg);
      expect(missingUserMsg).toBe(LOGIN_FAILED_MESSAGE);
    });
  });
});

