import { Injectable } from '@nestjs/common';
import { PassportStrategy } from '@nestjs/passport';
import type { VerifyCallback } from 'passport-oauth2';
import { Strategy } from 'passport-google-oauth20';
import { AuthService } from '../auth.service';

interface GoogleProfile {
  emails?: Array<{ value: string }>;
}

@Injectable()
export class GoogleStrategy extends PassportStrategy(Strategy, 'google') {
  private disabled = false;

  constructor(private readonly authService: AuthService) {
    const clientID = process.env.GOOGLE_CLIENT_ID;
    const clientSecret = process.env.GOOGLE_CLIENT_SECRET;
    const wouldBeDisabled = !clientID || !clientSecret;

    super({
      clientID: clientID ?? 'DUMMY_GOOGLE_CLIENT_ID',
      clientSecret: clientSecret ?? 'DUMMY_GOOGLE_CLIENT_SECRET',
      callbackURL:
        process.env.GOOGLE_CALLBACK_URL ||
        'http://localhost:3000/auth/google/callback',
      scope: ['profile', 'email'],
    });

    if (wouldBeDisabled) {
      this.disabled = true;
    }
  }

  async validate(
    accessToken: string,
    refreshToken: string,
    profile: GoogleProfile,
    done: VerifyCallback,
  ) {
    if (this.disabled) {
      return done(new Error('GoogleStrategy is disabled'));
    }
    try {
      const email = profile.emails?.[0]?.value;
      if (!email) {
        return done(new Error('No email found in Google profile'));
      }

      const user = await this.authService.findOrCreateOAuthUser(email);

      return done(null, {
        id: user.id,
        email: user.email,
      });
    } catch (error) {
      return done(error as Error);
    }
  }
}

import { Injectable } from '@nestjs/common';
import { PassportStrategy } from '@nestjs/passport';
import type { VerifyCallback } from 'passport-oauth2';
import { Strategy } from 'passport-facebook';
import { AuthService } from '../auth.service';

interface FacebookProfile {
  emails?: Array<{ value: string }>;
}

@Injectable()
export class FacebookStrategy extends PassportStrategy(Strategy, 'facebook') {
  private disabled = false;

  constructor(private readonly authService: AuthService) {
    const appID = process.env.FACEBOOK_APP_ID;
    const appSecret = process.env.FACEBOOK_APP_SECRET;
    const wouldBeDisabled = !appID || !appSecret;

    super({
      clientID: appID ?? 'DUMMY_FACEBOOK_APP_ID',
      clientSecret: appSecret ?? 'DUMMY_FACEBOOK_APP_SECRET',
      callbackURL:
        process.env.FACEBOOK_CALLBACK_URL ||
        'http://localhost:3000/auth/facebook/callback',
      profileFields: ['id', 'displayName', 'emails'],
    });

    if (wouldBeDisabled) {
      this.disabled = true;
    }
  }

  async validate(
    accessToken: string,
    refreshToken: string,
    profile: FacebookProfile,
    done: VerifyCallback,
  ) {
    if (this.disabled) {
      return done(new Error('FacebookStrategy is disabled'));
    }
    try {
      const email = profile.emails?.[0]?.value;
      if (!email) {
        return done(new Error('No email found in Facebook profile'));
      }

      const user = await this.authService.findOrCreateOAuthUser(email);

      return done(null, {
        id: user.id,
        email: user.email,
      });
    } catch (error) {
      return done(error as Error);
    }
  }
}

import { Transform } from 'class-transformer';
import {
  IsEmail,
  IsOptional,
  IsString,
  Matches,
  MaxLength,
} from 'class-validator';

function trimEmail({ value }: { value: unknown }) {
  return typeof value === 'string' ? value.trim() : value;
}

function trimOptionalDisplayName({ value }: { value: unknown }) {
  if (typeof value !== 'string') return undefined;
  const t = value.trim();
  return t.length > 0 ? t : undefined;
}

/** Matches T-106 / design: upper, lower, digit, one of !@#$%^&*, length 8–72 */
export const REGISTER_PASSWORD_PATTERN =
  /^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)(?=.*[!@#$%^&*]).{8,72}$/;

export const REGISTER_PASSWORD_MESSAGE =
  'Password must be 8–72 characters and include uppercase, lowercase, a number, and a special character (!@#$%^&*)';

export class RegisterDto {
  @Transform(trimEmail)
  @IsEmail()
  @MaxLength(255)
  email!: string;

  @IsOptional()
  @Transform(trimOptionalDisplayName)
  @IsString()
  @MaxLength(255)
  displayName?: string;

  @IsString()
  @MaxLength(72)
  @Matches(REGISTER_PASSWORD_PATTERN, { message: REGISTER_PASSWORD_MESSAGE })
  password!: string;
}

import { plainToInstance } from 'class-transformer';
import { validate } from 'class-validator';
import {
  RegisterDto,
  REGISTER_PASSWORD_MESSAGE,
  REGISTER_PASSWORD_PATTERN,
} from './register.dto';

describe('RegisterDto', () => {
  it('rejects weak passwords', async () => {
    const weak = ['password', '12345678', 'Password1', 'Password!', 'passWord1'];
    for (const password of weak) {
      const dto = plainToInstance(RegisterDto, {
        email: 'a@b.com',
        password,
      });
      const errors = await validate(dto);
      expect(errors.length).toBeGreaterThan(0);
      const pwdErr = errors.find((e) => e.property === 'password');
      expect(pwdErr?.constraints?.matches).toBe(REGISTER_PASSWORD_MESSAGE);
    }
  });

  it('accepts a compliant password', async () => {
    const dto = plainToInstance(RegisterDto, {
      email: '  user@example.com  ',
      password: 'Password123!',
      displayName: '  Ada  ',
    });
    const errors = await validate(dto);
    expect(errors).toHaveLength(0);
    expect(dto.email).toBe('user@example.com');
    expect(REGISTER_PASSWORD_PATTERN.test(dto.password)).toBe(true);
    expect(dto.displayName).toBe('Ada');
  });

  it('trims email and drops empty displayName', async () => {
    const dto = plainToInstance(RegisterDto, {
      email: '  trim@example.com ',
      password: 'Aa1!aaaa',
      displayName: '   ',
    });
    const errors = await validate(dto);
    expect(errors).toHaveLength(0);
    expect(dto.email).toBe('trim@example.com');
    expect(dto.displayName).toBeUndefined();
  });
});

import { Transform } from 'class-transformer';
import {
  IsEmail,
  IsNotEmpty,
  IsString,
  MaxLength,
} from 'class-validator';

export class LoginDto {
  @Transform(({ value }) => (typeof value === 'string' ? value.trim() : value))
  @IsEmail()
  @MaxLength(255)
  email!: string;

  /** Login does not enforce register-style min length (avoids leaking policy via 400 vs 401). */
  @IsString()
  @IsNotEmpty({ message: 'Password is required' })
  @MaxLength(72)
  password!: string;
}

import { plainToInstance } from 'class-transformer';
import { validate } from 'class-validator';
import { LoginDto } from './login.dto';

describe('LoginDto', () => {
  it('rejects empty email or password', async () => {
    const empty = plainToInstance(LoginDto, { email: '', password: '' });
    const e1 = await validate(empty);
    expect(e1.length).toBeGreaterThan(0);

    const noPwd = plainToInstance(LoginDto, {
      email: 'a@b.com',
      password: '',
    });
    const e2 = await validate(noPwd);
    expect(e2.some((x) => x.property === 'password')).toBe(true);
  });

  it('accepts valid credentials shape', async () => {
    const dto = plainToInstance(LoginDto, {
      email: '  user@example.com ',
      password: 'x',
    });
    const errors = await validate(dto);
    expect(errors).toHaveLength(0);
    expect(dto.email).toBe('user@example.com');
  });
});

